 2	
 3	import (
 4		"bytes"
 5		"fmt"
 6		"io"
 7		"mime/multipart"
 8	)
 9	
10	// NewFile encodes src as a multipart/form-data body with a single file part.
11	//
12	// It returns the Content-Type header value and a *bytes.Reader over the
13	// encoded body. Because *bytes.Reader is recognized by http.NewRequest,
14	// the resulting request automatically gets a working GetBody, which
15	// makes retries (e.g. on 429 / 5xx) safe without any extra wiring.
16	func NewFile(fieldName, fileName string, src io.Reader) (string, *bytes.Reader, error) {
17		if fieldName == "" {
18			return "", nil, fmt.Errorf("multipart field name is required")
19		}
20		if fileName == "" {
21			return "", nil, fmt.Errorf("multipart file name is required")
22		}
23		if src == nil {
24			return "", nil, fmt.Errorf("multipart file content is required")
25		}
26	
27		var buf bytes.Buffer
28		writer := multipart.NewWriter(&buf)
29	
30		part, err := writer.CreateFormFile(fieldName, fileName)
31		if err != nil {
32			return "", nil, fmt.Errorf("create multipart file: %w", err)
33		}
34		if _, err := io.Copy(part, src); err != nil {
35			return "", nil, fmt.Errorf("write multipart file: %w", err)
36		}
37		if err := writer.Close(); err != nil {
38			return "", nil, fmt.Errorf("close multipart writer: %w", err)
39		}
40	
41		return writer.FormDataContentType(), bytes.NewReader(buf.Bytes()), nil
42	}

